import sys

def main():
    n = int(sys.stdin.readline().strip())
    if n <= 0:
        print()
        return

    result = []
    num = 1

    while len(result) < n:
        if num > 50:
            break
        if num % 3 != 0:
            result.append(num)
        num += 1

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
